const raw = $input.item.json;

function extractText(value) {
  if (typeof value === 'string') { return value; }
  if (Array.isArray(value)) {
    return value.filter(function (block) { return block && (block.type === 'text' || typeof block.text === 'string'); }).map(function (block) { return block.text; }).join('\n');
  }
  if (value && typeof value === 'object') {
    if (typeof value.text === 'string') { return value.text; }
    if (typeof value.output === 'string') { return value.output; }
  }
  return '';
}

let text = extractText(raw.content) || extractText(raw.text) || extractText(raw.output) || extractText(raw);
text = (text || '').trim();
text = text.replace(/^```(json)?/i, '').replace(/```$/, '').trim();

if (!text) {
  throw new Error('Kon geen tekst uit het AI-antwoord halen: ' + JSON.stringify(raw).slice(0, 500));
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('AI-antwoord was geen geldige JSON: ' + text.slice(0, 500));
}

const lead = $('Invoer opschonen').item.json;

return {
  naam: lead.naam,
  email: lead.email,
  bedrijf: lead.bedrijf,
  telefoon: lead.telefoon,
  vraag: lead.vraag,
  ruwe_payload: lead.ruwe_payload,
  samenvatting: parsed.samenvatting || '',
  segment: parsed.segment || '',
  urgentie: parsed.urgentie || '',
  eerste_actie: parsed.eerste_actie || ''
};
